def calcul_startdate(prod_code):
    row = []
    stock_code = prod_code.split('.')[0]
    BASE_DIR = '%s/IndexNumberDownLoad/blockCodes' % DATADIR
    file = f'{BASE_DIR!s}/{stock_code!s}.csv'
    with open(file, 'rt') as fin:
        cin = csv.reader(fin)
        for i, lines in enumerate(cin):
            row.append(lines)
        else:
            if row:
                startdate = min([x[1] for x in row])
            else:
                startdate = time.strftime('%Y%m%d', time.localtime())
    return startdate
