def get_benchmark_returns_local(end_date):
    benchmark_path = '%s/Benchmark/benchmark.csv' % DATADIR
    tmpPd = pandas.read_csv(benchmark_path)
    tmpPd = pandas.Series([i for i in tmpPd['Adj Close'].pct_change(1).values], index=[pandas.Timestamp(datetime.datetime.strptime(j, '%Y/%m/%d').replace(pytz.utc)) for j in tmpPd['Date']]).iloc[1:]
    tmpPd_end_date = tmpPd.index[-1:][0]
    tmpPd_end_value = tmpPd[-1:][0]
    if end_date > tmpPd_end_date:
        temp_index = pandas.date_range(start=tmpPd_end_date, end=end_date, freq='B')
        if len(temp_index) > 1:
            temp_index = temp_index[1:]
            index = []
            holidays = get_holiday_local()
            for item in temp_index:
                if item.strftime('%Y%m%d') not in holidays:
                    index.append(item)
            else:
                tmpPd1 = pandas.Series([tmpPd_end_value for i in range(len(index))], index=index)
                tmpPd = tmpPd.append(tmpPd1)
    return tmpPd
