def load_future_info_local(contract_code, market_code):
    """
    从对应期货合约数据源加载合约信息
    :param contract_code: 交易代码, 如IF1709, CU1709
    :param market_code: 市场代码, 如CCFX, XDEC
    :return: 返回Dict
    """
    def get_trade_code(contract_code):
        """
        获取期货合约交易代码，如IF1709，返回IF
        :param contract_code: 期货合约交易代码，如IF1709
        :return:
        """
        trade_code = ''
        for c in contract_code:
            if c.isdigit():
                break
            trade_code += c
        return trade_code
    trade_code = get_trade_code(contract_code)
    fileName = f'{DATADIR!s}/FutureContract/{market_code!s}/{trade_code!s}.csv'
    if os.path.exists(fileName):
        src_df = pandas.read_csv(fileName, encoding='utf-8', dtype=str)
        src_df.sort_values('contract_code', inplace=True)
        _where_str = "contract_code <= '%s'" % contract_code
        dst_df = src_df.query(_where_str).iloc[-1, :]
        return dst_df.to_dict()
