def get_valuation_info(count, date, stocks):
    result = {}
    date = pandas.Timestamp(date)
    if len(stocks) > 500:
        stocks = list(stocks)
        df_list_iterator = get_all_valuation(stocks)
        for stock, df in df_list_iterator:
            i = get_index(df.index, date)
            if i < count:
                df = df.iloc[:i]
            else:
                df = df.iloc[i - count:i]
            result[stock] = df
    else:
        for stock in stocks:
            df = get_one_valuation(stock)
            i = get_index(df.index, date)
            if i < count:
                df = df.iloc[:i]
            else:
                df = df.iloc[i - count:i]
            result[stock] = df
    return result
