def get_index(index, key):
    while end - start > 1:
        middle = (start + end) // 2
        m = index[middle]
        if m == key:
            return middle + 1
        elif m < key:
            start = middle
        else:
            end = middle
        end - start
def get_one_valuation(stock):
    code, market = stock.split('.')[:2]
    if market in {'SS', 'XSHG'}:
        stock_dir = 'XSHG'
    elif market in {'SZ', 'XSHE'}:
        stock_dir = 'XSHE'
    else:
        raise ParamsError('不支持的股票市场')
    valuation_file = os.path.join(valuation_path, stock_dir, code + '.pickle')
    if os.path.exists(valuation_file):
        return pandas.read_pickle(valuation_file)
    else:
        return pandas.DataFrame(columns=valuation_columns)
def get_all_valuation(stocks):
    valuation_file = os.path.join(valuation_path, 'all.pickle')
    if os.path.exists(valuation_file):
        df_dict = pandas.read_pickle(valuation_file)
        for stock in stocks:
            code = stock.split('.')[0]
            if code in df_dict:
                yield (stock, df_dict[code])
                continue
            yield (stock, pandas.DataFrame(columns=valuation_columns))
    else:
        for stock in stocks:
            yield (stock, get_one_valuation(stock))
