        for stk in stocks:
            info_dict = {}
            stk_alt = stk.replace('SS', 'XSHG').replace('SZ', 'XSHE')
            if stk_alt in df.index:
                info_dict['stock_name'] = df.stock_name.get(stk_alt, '')
                listed_date = str(df.List_date.get(stk_alt, ''))
                de_listed_date = str(df.Delisting_date.get(stk_alt, ''))
            elif stk_alt in cb_df.index:
                info_dict['stock_name'] = cb_df.stock_name.get(stk_alt, '')
                listed_date = str(cb_df.List_date.get(stk_alt, ''))
                de_listed_date = str(cb_df.Delisting_date.get(stk_alt, ''))
            elif stk_alt in etf_df.index:
                info_dict['stock_name'] = etf_df.stock_name.get(stk_alt, '')
                listed_date = str(etf_df.List_date.get(stk_alt, ''))
                de_listed_date = str(etf_df.Delisting_date.get(stk_alt, ''))
